private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Handle null references or non-positive index gracefully
    if (bb == null || sb == null || i < 0) {
        return i;
    }
    int limit = bb.limit();
    if (i >= limit) {
        return i; // nothing to decode
    }
    int byte1 = bb.get(i) & 0xFF;
    int n = 0;       // number of bytes consumed
    int codePoint = 0;

    // Determine sequence length from the leading bits
    int prefix = byte1 >> 5;
    switch (prefix) {
        case 0: // 0xxxxxxx (single byte ASCII)
            n = 1;
            codePoint = byte1;
            break;
        case 6: // 110xxxxx
            if (i + 1 >= limit) {
                return i; // incomplete sequence
            }
            int byte2 = bb.get(i + 1) & 0xFF;
            if ((byte2 & 0xC0) != 0x80) {
                return i; // invalid continuation byte
            }
            n = 2;
            codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
            break;
        case 14: // 1110xxxx
            if (i + 2 >= limit) {
                return i; // incomplete sequence
            }
            byte2 = bb.get(i + 1) & 0xFF;
            int byte3 = bb.get(i + 2) & 0xFF;
            if ((byte2 & 0xC0) != 0x80 || (byte3 & 0xC0) != 0x80) {
                return i; // invalid continuation bytes
            }
            n = 3;
            codePoint = ((byte1 & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F);
            break;
        case 30: // 11110xxx
            if (i + 3 >= limit) {
                return i; // incomplete sequence
            }
            byte2 = bb.get(i + 1) & 0xFF;
            byte3 = bb.get(i + 2) & 0xFF;
            int byte4 = bb.get(i + 3) & 0xFF;
            if ((byte2 & 0xC0) != 0x80 || (byte3 & 0xC0) != 0x80 || (byte4 & 0xC0) != 0x80) {
                return i; // invalid continuation bytes
            }
            n = 4;
            codePoint = ((byte1 & 0x07) << 18) | ((byte2 & 0x3F) << 12) |
                        ((byte3 & 0x3F) << 6) | (byte4 & 0x3F);
            break;
        default:
            return i; // invalid first byte
    }

    // Append the decoded character(s) to the StringBuilder
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        // Encode as UTF-16 surrogate pair
        codePoint -= 0x10000;
        sb.append((char) ((codePoint >> 10) + 0xD800));
        sb.append((char) ((codePoint & 0x3FF) + 0xDC00));
    }
    return i + n;
}

