private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    // Assume the backing array is called 'code'
    // If the field is named differently, adjust accordingly.
    if (this.code == null) {
        throw new IllegalStateException("Backing array 'code' is null");
    }
    int currentLen = this.code.length;
    long required = (long) currentLen + size; // use long to detect overflow
    if (required <= currentLen) { // overflow or no need to enlarge
        return;
    }
    int newCapacity;
    try {
        newCapacity = (int) Math.min(required, Integer.MAX_VALUE - 1);
    } catch (ArithmeticException e) {
        throw new IllegalArgumentException("Requested size too large", e);
    }
    // Grow by 50% plus the required extra to be efficient
    int grow = currentLen / 2 + size;
    newCapacity = Math.max(newCapacity, currentLen + grow);
    byte[] newCode = new byte[newCapacity];
    System.arraycopy(this.code, 0, newCode, 0, currentLen);
    this.code = newCode;
}

protected static void deleteFile(String fileName) {
    // Validate the input
    if (fileName == null || fileName.trim().isEmpty()) {
        // No action needed for null or blank names – quietly return
        return;
    }

    java.io.File file = new java.io.File(fileName);

    // If the file does not exist, there's nothing to delete
    if (!file.exists()) {
        return;
    }

    try {
        // Attempt to delete the file or directory
        if (!file.delete()) {
            // If deletion fails, throw a RuntimeException to signal the caller
            throw new RuntimeException("Unable to delete file: " + fileName);
        }
    } catch (SecurityException se) {
        // Wrap the security exception in a RuntimeException so the caller doesn't need to
        // declare it in the method signature
        throw new RuntimeException("Security exception while deleting file: " + fileName, se);
    }
}

public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        int elementHash = (int) (value ^ (value >>> 32));
        result = 31 * result + elementHash;
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        // Nothing to rotate
        return node;
    }

    // Move left child's right subtree to node's left subtree
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    // Perform rotation
    leftChild.right = node;

    // Update parent references
    leftChild.parent = node.parent;
    if (node.parent == null) {
        // node was root; after rotation, leftChild becomes the new root
        // Caller should update the tree root reference as needed
    } else if (node.parent.left == node) {
        node.parent.left = leftChild;
    } else {
        node.parent.right = leftChild;
    }

    node.parent = leftChild;

    return leftChild;
}

