public String format(LoggingEvent event){
    if(event == null){
        return "";
    }
    // Use the configured pattern; fallback to a default if not set
    String pattern = this.conversionPattern;
    if(pattern == null || pattern.isEmpty()){
        pattern = "%d{yyyy-MM-dd HH:mm:ss} [%t] %-5p %c - %m%n";
    }
    StringBuilder sb = new StringBuilder();
    try{
        for(int i = 0; i < pattern.length(); i++){
            char c = pattern.charAt(i);
            if(c == '%' && i + 1 < pattern.length()){
                char next = pattern.charAt(i + 1);
                switch(next){
                    case 'm':
                        sb.append(event.getFormattedMessage());
                        i++;
                        break;
                    case 't':
                        sb.append(event.getThreadName());
                        i++;
                        break;
                    case 'c':
                        sb.append(event.getLoggerName());
                        i++;
                        break;
                    case 'd':
                        // Optional date format in curly braces
                        String dateFormat = "yyyy-MM-dd HH:mm:ss";
                        int idx = i + 2;
                        if(idx < pattern.length() && pattern.charAt(idx) == '{'){
                            int end = pattern.indexOf('}', idx);
                            if(end > idx){
                                dateFormat = pattern.substring(idx + 1, end);
                                i = end;
                            }
                        }
                        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat(dateFormat);
                        sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
                        i++;
                        break;
                    case 'p':
                        // log level, if available
                        Object levelObj = event.getLevel();
                        sb.append(levelObj != null ? levelObj.toString() : "UNKNOWN");
                        i++;
                        break;
                    case 'n':
                        sb.append(System.lineSeparator());
                        i++;
                        break;
                    case '%':
                        sb.append('%');
                        i++;
                        break;
                    default:
                        sb.append(c);
                }
            } else {
                sb.append(c);
            }
        }
    } catch (Exception ex){
        // In case of formatting failure, return an empty string
        return "";
    }
    return sb.toString();
}

