public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }
    // Find last index of both path separators
    int lastSlash = filename.lastIndexOf('/');
    int lastBackslash = filename.lastIndexOf('\\');
    // Return the greatest of the indices (or -1 if none found)
    return Math.max(lastSlash, lastBackslash);
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart must not be null");
    }
    /* start scanning from the next character after the last processed byte */
    int start = end + 1;
    if (start < 0) {
        start = 0;
    }
    for (int i = start; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    /* if no CRLF sequence is found, indicate not found with -1 */
    return -1;
}

