public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Validate input
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null");
    }
    try {
        // Define the sizes of the two partitions. Adjust as needed for your test requirements.
        int leftSize = 3;
        int rightSize = 3;

        List<V> leftVertices = new ArrayList<>();
        List<V> rightVertices = new ArrayList<>();

        // Create vertices for the left partition
        for (int i = 0; i < leftSize; i++) {
            // Use a string representation for the vertex and cast to V (unchecked)
            @SuppressWarnings("unchecked")
            V vertex = (V) ("L" + i);
            boolean added = target.addVertex(vertex);
            if (!added) {
                throw new RuntimeException("Failed to add vertex: " + vertex);
            }
            resultMap.put("L" + i, vertex);
            leftVertices.add(vertex);
        }

        // Create vertices for the right partition
        for (int i = 0; i < rightSize; i++) {
            @SuppressWarnings("unchecked")
            V vertex = (V) ("R" + i);
            boolean added = target.addVertex(vertex);
            if (!added) {
                throw new RuntimeException("Failed to add vertex: " + vertex);
            }
            resultMap.put("R" + i, vertex);
            rightVertices.add(vertex);
        }

        // Add edges between every pair of vertices from the two partitions
        for (V left : leftVertices) {
            for (V right : rightVertices) {
                // For Graph implementations that require an edge supplier, addEdge may return an edge instance.
                // The returned edge is ignored here.
                target.addEdge(left, right);
            }
        }
    } catch (ClassCastException e) {
        throw new RuntimeException("Failed to cast vertex to the generic type V", e);
    } catch (Exception e) {
        throw new RuntimeException("Unexpected error while generating complete bipartite graph", e);
    }
}

protected int findByte(byte value, int pos) {
    // If the buffer is null or empty, the value cannot be found.
    if (buffer == null || buffer.length == 0) {
        return -1;
    }
    // Clamp the starting position to the valid index range.
    if (pos < 0) {
        pos = 0;
    }
    if (pos >= buffer.length) {
        return -1;
    }
    // Search sequentially from the starting position onward.
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i; // Return the index where the value was found.
        }
    }
    // If the loop completes, the value is not present in the buffer.
    return -1;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    // Ensure we have a buffer; if none provided, create a temporary one for this call
    if (buffer == null) {
        buffer = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE);
    }
    // Compute serialized size
    int size = schema.getSerializedSize(message, buffer);
    // Write the length prefix (as a 4‑byte big‑endian integer)
    out.write((size >> 24) & 0xFF);
    out.write((size >> 16) & 0xFF);
    out.write((size >> 8) & 0xFF);
    out.write(size & 0xFF);
    // Serialize the message itself
    schema.writeTo(out, message, buffer);
    return size;
}

