int addType(final String value){
    if (value == null) {
        throw new IllegalArgumentException("Value cannot be null");
    }
    // Initialize the type table if it hasn't been created yet
    if (typeTable == null) {
        typeTable = new java.util.ArrayList<>();
    }
    // Search for an existing type with the same value
    for (int i = 0; i < typeTable.size(); i++) {
        if (value.equals(typeTable.get(i))) {
            return i; // already exists
        }
    }
    // Add the new type and return its index
    typeTable.add(value);
    return typeTable.size() - 1;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (genericType == null || targetType == null) {
            return null;
        }
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType pType = (ParameterizedType) genericType;
        Type[] args = pType.getActualTypeArguments();
        if (args == null || args.length == 0) {
            return new Class<?>[0];
        }
        Class<?>[] resolved = new Class<?>[args.length];
        for (int i = 0; i < args.length; i++) {
            Type t = args[i];
            if (t instanceof Class<?>) {
                resolved[i] = (Class<?>) t;
            } else if (t instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) t).getRawType();
                if (raw instanceof Class<?>) {
                    resolved[i] = (Class<?>) raw;
                } else {
                    return null; // cannot resolve non-Class raw type
                }
            } else {
                return null; // includes WildcardType, GenericArrayType, TypeVariable
            }
        }
        return resolved;
    } catch (Exception e) {
        return null;
    }
}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    try {
        // Retrieve existing value from cache
        METRICS existing = cache.get(data);
        if (existing != null) {
            // Attempt to merge if a merge method exists
            try {
                java.lang.reflect.Method mergeMethod = data.getClass().getMethod("merge", data.getClass());
                mergeMethod.invoke(existing, data);
            } catch (NoSuchMethodException ignored) {
                // If no merge method, replace the old value
                cache.put(data, data);
            }
        } else {
            // No existing entry, simply put the new data
            cache.put(data, data);
        }
    } catch (Exception ex) {
        // Wrap any reflection or cache errors in a runtime exception
        throw new RuntimeException("Failed to accept METRICS into cache", ex);
    }
}

void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Target bucket cannot be null");
    }
    // Link this bucket before the provided bucket
    this.next = bucket;
    this.prev = bucket.prev;
    // If there was a previous bucket, reconnect its next pointer to this bucket
    if (bucket.prev != null) {
        bucket.prev.next = this;
    }
    // Finally, set the target bucket's previous pointer to this bucket
    bucket.prev = this;
}

