public long readLong(final int offset){
    final byte[] b = this.b;
    if (offset < 0 || offset + 7 >= b.length) {
        throw new IllegalArgumentException("Offset out of bounds: " + offset);
    }
    return ((long)b[offset] << 56) |
           ((long)(b[offset + 1] & 255) << 48) |
           ((long)(b[offset + 2] & 255) << 40) |
           ((long)(b[offset + 3] & 255) << 32) |
           ((long)(b[offset + 4] & 255) << 24) |
           ((long)(b[offset + 5] & 255) << 16) |
           ((long)(b[offset + 6] & 255) << 8) |
           ((long)(b[offset + 7] & 255));
}

public boolean equals(final byte[] data,int offset,final int len){
    // Return false if the provided array is null
    if (data == null) {
        return false;
    }
    // Validate offset and length are non‑negative and within bounds
    if (offset < 0 || len < 0 || (long) offset + len > data.length) {
        return false;
    }
    // Access the internal array (assumed to be stored in a field named 'bytes')
    byte[] internal = this.bytes;
    // If the internal array is null the only possibility for equality is an empty slice
    if (internal == null) {
        return len == 0 && offset == 0 && data.length == 0;
    }
    // Lengths must match
    if (internal.length != len) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < len; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

