public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must not be negative");
    }
    // No bytes to copy
    if (byteLength == 0) {
        return this;
    }

    // Ensure the internal buffer exists
    if (this.array == null) {
        // initial capacity of 32 or larger than required
        int initCap = Math.max(32, byteLength);
        this.array = new byte[initCap];
    }

    // Calculate new position after insertion
    int newPos = this.pos + byteLength;
    // Resize if necessary
    if (newPos > this.array.length) {
        int newCapacity = Math.max(newPos, this.array.length * 2);
        byte[] newArray = new byte[newCapacity];
        System.arraycopy(this.array, 0, newArray, 0, this.pos);
        this.array = newArray;
    }

    // Copy bytes
    if (byteArrayValue == null) {
        // Fill with zero bytes
        java.util.Arrays.fill(this.array, this.pos, newPos, (byte) 0);
    } else {
        // Validate offset bounds
        if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
            throw new IndexOutOfBoundsException(
                "byteOffset (" + byteOffset + ") + byteLength (" + byteLength + ") out of bounds for source array");
        }
        System.arraycopy(byteArrayValue, byteOffset, this.array, this.pos, byteLength);
    }

    // Update position
    this.pos = newPos;
    return this;
}

