public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Validate mandatory parameters
    if (str == null) {
        throw new NullPointerException("Input string cannot be null");
    }
    if (lb == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }
    // Convert the CharSequence to a UTF‑8 encoded byte array
    byte[] utf8Bytes;
    try {
        utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    } catch (Exception e) {
        // Normally this exception should never occur because UTF-8 is a supported charset
        throw new RuntimeException("Failed to encode string to UTF‑8", e);
    }

    // Write the bytes into the buffer
    try {
        // Netty's LinkedBuffer provides a writeBytes method
        // If the buffer type differs, this block should be adapted accordingly
        if (lb instanceof org.jboss.netty.buffer.ByteBuffer) {
            lb.writeBytes(utf8Bytes, 0, utf8Bytes.length);
        } else if (lb instanceof java.io.OutputStream) {
            ((java.io.OutputStream) lb).write(utf8Bytes);
        } else {
            // Fallback: try a generic method that many buffer implementations expose
            // If such method does not exist, this will cause a compile-time error
            lb.writeBytes(utf8Bytes, 0, utf8Bytes.length);
        }
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF‑8 bytes to buffer", e);
    }

    // Return the buffer to allow chaining
    return lb;
}

public void removeFromTreeEdgeList(){
