public static String findAndSubst(String key, Properties props) {
    try {
        String val = props.getProperty(key);
        if (val == null) {
            return null;
        }
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        java.util.regex.Matcher matcher = pattern.matcher(val);
        java.lang.StringBuilder result = new java.lang.StringBuilder();
        int lastEnd = 0;
        while (matcher.find()) {
            result.append(val, lastEnd, matcher.start());
            String subKey = matcher.group(1);
            String subVal = findAndSubst(subKey, props);
            if (subVal == null) {
                subVal = "";
            }
            result.append(subVal);
            lastEnd = matcher.end();
        }
        result.append(val.substring(lastEnd));
        return result.toString();
    } catch (Exception e) {
        return null;
    }
}

