    return str.regionMatches(ignoreCase, str.length() - suffix.length(), suffix, 0, suffix.length());
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String path = u.getPath();
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (path == null || path.isEmpty() || path.equals("/")) {
        return segments;
    }

    // Remove leading '/' if present for absolute paths
    int startIndex = path.startsWith("/") ? 1 : 0;
    String trimmedPath = path.substring(startIndex);

    // Split on '/', ignore empty segments that may arise from trailing slashes
    String[] parts = trimmedPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported; fallback to original segment
                value = part;
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

