private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    final int len = descriptor.length();
    if (len == 0) {
        return;
    }
    int i = 0;
    boolean isMethod = false;
    if (descriptor.charAt(i) == '(') {
        isMethod = true;
        i++; // skip '('
    }
    while (true) {
        // Stop if we reached end or colon for method return type
        if (i >= len || (!isMethod && i == 0)) {
            break;
        }
        // For method descriptor, stop at ')'
        if (isMethod && descriptor.charAt(i) == ')') {
            i++; // skip ')'
            break;
        }
        int slots = 0;
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B': case 'C': case 'F': case 'I':
            case 'S': case 'Z':
                slots = 1;
                i++;
                break;
            case 'J': case 'D':
                slots = 2;
                i++;
                break;
            case '[':
                // Skip all '['
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                // Skip component type
                char comp = descriptor.charAt(i);
                if (comp == 'L') {
                    // object type component
                    i++; // skip 'L'
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= len) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i++; // skip ';'
                } else {
                    // base type component (one char)
                    i++;
                }
                slots = 1;
                break;
            case 'L':
                // object type
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i++; // skip ';'
                slots = 1;
                break;
            default:
                throw new IllegalArgumentException("Unexpected type code in descriptor: " + c);
        }
        // Pop the determined number of slots from the output frame stack
        for (int s = 0; s < slots; s++) {
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Insufficient values on output stack");
            }
            outputFrameStack.remove(outputFrameStack.size() - 1);
        }
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b");
    }
    if (off < 0 || len < 0 || (off + len) > b.length) {
        throw new IndexOutOfBoundsException();
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        // Grow the buffer
        int newCapacity = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

