    }
    int len = arr.length;
    if (i < 0 || i >= len || j < 0 || j >= len) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    if (i == j) {
        return; // no-op
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

public Boolean isPartialContentResponse() {
    if (actualResponse == null) {
        return false;
    }
    try {
        int status = -1;
        if (actualResponse instanceof javax.ws.rs.core.Response) {
            status = ((javax.ws.rs.core.Response) actualResponse).getStatus();
        } else if (actualResponse instanceof org.springframework.http.ResponseEntity) {
            status = ((org.springframework.http.ResponseEntity<?>) actualResponse).getStatusCodeValue();
        } else if (actualResponse instanceof org.apache.http.HttpResponse) {
            status = ((org.apache.http.HttpResponse) actualResponse).getStatusLine().getStatusCode();
        } else {
            java.lang.reflect.Method method = actualResponse.getClass().getMethod("getStatus");
            status = (int) method.invoke(actualResponse);
        }
        return status == 206;
    } catch (Exception e) {
        return false;
    }
}

