private static File[] classPath() {
    try {
        String path = System.getProperty("java.class.path");
        if (path == null || path.isEmpty()) {
            return new File[0];
        }
        String[] parts = path.split(java.util.regex.Pattern.quote(File.pathSeparator));
        int count = 0;
        for (String part : parts) {
            if (!part.isEmpty()) {
                count++;
            }
        }
        File[] files = new File[count];
        int idx = 0;
        for (String part : parts) {
            if (!part.isEmpty()) {
                files[idx++] = new File(part);
            }
        }
        return files;
    } catch (SecurityException e) {
        // Unable to access the system property; return an empty array
        return new File[0];
    } catch (Exception e) {
        // Unexpected exception; return an empty array
        return new File[0];
    }
}

