public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box must not be null");
    }
    try {
        double minX = box.getMinX();
        double maxX = box.getMaxX();
        double minY = box.getMinY();
        double maxY = box.getMaxY();
        double midY = (minY + maxY) / 2.0;

        Box2D firstHalf = new Box2D(minX, minY, maxX, midY);
        Box2D secondHalf = new Box2D(minX, midY, maxX, maxY);

        return new Pair<>(firstHalf, secondHalf);
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to split the box: " + e.getMessage(), e);
    }
}

private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("size must be positive");
    }
    int currentCapacity = (buffer != null) ? buffer.length : 0;
    int newCapacity;
    if (currentCapacity == 0) {
        newCapacity = Math.max(16, size);
    } else {
        long required = (long) this.size + size;
        long doubled = (long) currentCapacity * 2;
        long cap = Math.max(doubled, required);
        if (cap > Integer.MAX_VALUE) {
            throw new OutOfMemoryError("Required capacity exceeds maximum array size");
        }
        newCapacity = (int) cap;
    }
    byte[] newBuffer = new byte[newCapacity];
    if (buffer != null) {
        System.arraycopy(buffer, 0, newBuffer, 0, this.size);
    }
    buffer = newBuffer;
}

