        if(bucketList == null || bucketSize == 0) return false;
        int bucketIdx = Math.abs(val) % bucketSize;
        java.util.List<Integer> bucket = bucketList.get(bucketIdx);
        if(bucket == null){
            bucket = new java.util.ArrayList<>();
            bucketList.set(bucketIdx, bucket);
        }
        for(int existing : bucket){
            if(existing == val){
                return false;
            }
        }
        bucket.add(val);
        return true;
    }catch(Exception e){
        // In case of any unexpected error, do not insert
        return false;
    }
}

