    LinkedBuffer current = node;
    while (current != null) {
        int len = current.position; // bytes stored in this buffer
        if (len > 0) {
            out.write(current.buffer, 0, len);
            totalSize += len;
        }
        current = current.next;
    }
    return totalSize;
}

