private void putAbstractTypes(final int start, final int end){
    // Validate inputs
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is not initialized");
    }
    if (stackMapTableEntries == null) {
        throw new IllegalStateException("stackMapTableEntries is not initialized");
    }
    if (start < 0) {
        throw new IllegalArgumentException("start index must be non‑negative");
    }
    if (end < start) {
        // nothing to write
        return;
    }

    // Limit the iteration to the real length of currentFrame
    final int maxIndex = Math.min(end, currentFrame.length);
    int i = start;
    while (i < maxIndex) {
        final int tag = currentFrame[i];
        // Write the verification_type_info tag
        stackMapTableEntries.add(tag);

        // Types OBJECT (7) and UNINIT (8) carry an additional u2/u4 value.
        if (tag == 7 || tag == 8) {
            if (i + 1 >= currentFrame.length) {
                throw new ArrayIndexOutOfBoundsException(
                    "Missing additional data for tag " + tag + " at index " + i);
            }
            stackMapTableEntries.add(currentFrame[i + 1]);
            i++; // skip the additional value
        }
        i++;
    }
}

public void readFrom(final InputStream in) throws IOException {
