    byte[] tempBuf = new byte[8192];
    int readCount;
    while ((readCount = in.read(tempBuf)) != -1) {
        baos.write(tempBuf, 0, readCount);
    }
    // Replace current buffer with the new data
    this.buf = baos.toByteArray();
    // Reset read pointer to start of the buffer
    this.ptr = 0;
}

