@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the requested target type is Character or primitive char
    if (type != Character.class && type != char.class) {
        throw new Exception("Target type must be java.lang.Character");
    }

    // null handling – simply return null
    if (value == null) {
        return null;
    }

    // Directly return if already a Character
    if (value instanceof Character) {
        return value;
    }

    // Handle CharSequence (String, StringBuilder, etc.)
    if (value instanceof CharSequence) {
        String str = value.toString();
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new Exception("Cannot convert String of length " + str.length() + " to java.lang.Character");
        }
    }

    // Handle numeric types – treat numeric value as Unicode code point
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < 0 || intVal > 0xFFFF) {
            throw new Exception("Numeric value out of character range: " + intVal);
        }
        return Character.valueOf((char) intVal);
    }

    // If none of the above, conversion is unsupported
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to java.lang.Character");
}

