public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Capacity must be positive; got " + desiredCapacity);
    }

    // If desired capacity is 1 or 2, return 2 as the smallest prime
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Determine the upper bound for the search if desiredCapacity is large
    int limit;
    if (desiredCapacity >= 1000) {
        long limitLong = (long) desiredCapacity * 111 / 100; // 110% of desiredCapacity
        if (limitLong > Integer.MAX_VALUE) {
            limit = Integer.MAX_VALUE;
        } else {
            limit = (int) limitLong;
        }
    } else {
        // For smaller capacities we don't enforce the 11% rule
        limit = Integer.MAX_VALUE;
    }

    // Helper lambda for primality test
    java.util.function.IntPredicate isPrime = n -> {
        if (n <= 3) {
            return n > 1;
        }
        if ((n & 1) == 0 || (n % 3) == 0) {
            return false;
        }
        int sqrt = (int) Math.sqrt(n);
        for (int i = 5; i <= sqrt; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    };

    // Search for the next prime
    int candidate = desiredCapacity;
    if (candidate == 2) {
        return 2;
    }
    if ((candidate & 1) == 0) {
        candidate++; // start with an odd number
    }
    while (candidate <= limit) {
        if (isPrime.test(candidate)) {
            return candidate;
        }
        // Avoid overflow when iterating near Integer.MAX_VALUE
        if (candidate > Integer.MAX_VALUE - 2) {
            break;
        }
        candidate += 2;
    }

    // If no prime found within the limit and limit is less than Integer.MAX_VALUE,
    // continue searching beyond the limit (unlikely for typical capacities).
    // Scan all integers from limit+1 upwards until a prime is found.
    candidate = limit + 1;
    if (candidate <= 2) {
        return 2;
    }
    if ((candidate & 1) == 0) {
        candidate++; // ensure odd
    }
    while (candidate > 0) { // guard against overflow
        if (isPrime.test(candidate)) {
            return candidate;
        }
        if (candidate > Integer.MAX_VALUE - 2) {
            break;
        }
        candidate += 2;
    }

    // As a last resort, return the maximum integer value if no prime was found.
    return Integer.MAX_VALUE;
}

