public static Object findFirstMatch(Collection source, Collection candidates) {
    if (source == null || candidates == null) {
        return null;
    }
    for (Object candidate : candidates) {
        try {
            if (source.contains(candidate)) {
                return candidate;
            }
        } catch (ClassCastException | NullPointerException e) {
            // If source contains incompatible types or has been modified concurrently,
            // we continue searching. The original spec doesn't require throwing.
            continue;
        }
    }
    return null;
}

public static String trimTrailingWhitespace(String str) {
    // Handle null input
    if (str == null) {
        return null;
    }
    int len = str.length();
    int i = len - 1;
    // Move backwards while there is whitespace at the end of the string
    while (i >= 0 && Character.isWhitespace(str.charAt(i))) {
        i--;
    }
    // If no trailing whitespace, return the original string
    if (i == len - 1) {
        return str;
    }
    // If the entire string was whitespace, return an empty string
    if (i < 0) {
        return "";
    }
    // Return the substring that excludes the trailing whitespace
    return str.substring(0, i + 1);
}

