}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
            continue;
        }
        // Count preceding backslashes including current
        int backslashCount = 0;
        int j = i;
        while (j >= 0 && str.charAt(j) == '\\') {
            backslashCount++;
            j--;
        }
        if ((backslashCount % 2) == 1) {
            // Current backslash is escaped -> literal backslash
            sb.append('\\');
            i++;
            continue;
        }
        // Current backslash is escape character
        if (i + 1 >= len) {
            throw new Exception("Trailing backslash at end of string");
        }
        char esc = str.charAt(i + 1);
        switch (esc) {
            case 'b':
                sb.append('\b');
                i += 2;
                break;
            case 'f':
                sb.append('\f');
                i += 2;
                break;
            case 'n':
                sb.append('\n');
                i += 2;
                break;
            case 'r':
                sb.append('\r');
                i += 2;
                break;
            case 't':
                sb.append('\t');
                i += 2;
                break;
            case '\'':
                sb.append('\'');
                i += 2;
                break;
            case '\"':
                sb.append('\"');
                i += 2;
                break;
            case '\\':
                sb.append('\\');
                i += 2;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new Exception("Invalid Unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                }
                i += 6;
                break;
            case 'x':
                if (i + 3 >= len) {
                    throw new Exception("Invalid hexadecimal escape sequence at position " + i);
                }
                String hex2 = str.substring(i + 2, i + 4);
                try {
                    int code = Integer.parseInt(hex2, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid hexadecimal escape sequence '\\x" + hex2 + "' at position " + i);
                }
                i += 4;
                break;
            default:
                if (esc >= '0' && esc <= '7') {
                    // Octal escape up to 3 digits
                    int end = i + 1;
                    while (end < len && end < i + 4 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                        end++;
                    }
                    String oct = str.substring(i + 1, end);
                    try {
                        int code = Integer.parseInt(oct, 8);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid octal escape sequence '\\" + oct + "' at position " + i);
                    }
                    i = end;
                } else {
                    throw new Exception("Unrecognized escape sequence '\\" + esc + "' at position " + i);
                }
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset){
    if (charset == null) {
        return null;
    }
    String name = charset.trim().toLowerCase();
    // Known MIME to Java mappings
    switch(name) {
        case "utf8":
        case "utf-8":
            return "UTF-8";
        case "iso-8859-1":
        case "iso8859-1":
            return "ISO-8859-1";
        case "iso-8859-2":
        case "iso8859-2":
            return "ISO-8859-2";
        case "us-ascii":
        case "usascii":
            return "US-ASCII";
        case "utf-16":
            return "UTF-16";
        case "utf-16be":
            return "UTF-16BE";
        case "utf-16le":
            return "UTF-16LE";
        case "windows-1252":
        case "x-windows-1252":
            return "windows-1252";
        default:
            // Try to resolve via Java charset registry
            try {
                java.nio.charset.Charset cs = java.nio.charset.Charset.forName(name);
                return cs.name();
            } catch (Exception e) {
                return null; // unknown charset
            }
    }
}

