final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Assumes the presence of an instance field: byte[] classFileBuffer
    if (classFileBuffer == null) {
        throw new IllegalArgumentException("classFileBuffer is null");
    }
    if (constantPoolEntryIndex < 1) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be >= 1");
    }
    if (classFileBuffer.length < 10) { // need at least magic + version + count
        throw new IllegalArgumentException("classFileBuffer is too short to contain a constant pool");
    }

    // Helper to read unsigned short (big endian)
    final int readU2(final int offset) {
        if (offset + 1 >= classFileBuffer.length) {
            throw new IllegalArgumentException("Unexpected end of classFileBuffer while reading u2");
        }
        return ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    }

    final int constantPoolCount = readU2(8); // constant_pool_count is at offset 8
    if (constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of range");
    }

    int offset = 10; // start of constant_pool[1]
    // walk to the requested entry
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        if (offset >= classFileBuffer.length) {
            throw new IllegalArgumentException("Unexpected end of classFileBuffer while skipping constant pool");
        }
        final int tag = classFileBuffer[offset] & 0xFF;
        switch (tag) {
            case 1: { // CONSTANT_Utf8
                final int len = readU2(offset + 1);
                offset += 3 + len;
                break;
            }
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
            case 16: // CONSTANT_MethodHandle
                offset += 5;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 9;
                // long/double occupy two constant pool entries
                i++; // skip the "unused" entry
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                offset += 3;
                break;
            case 15: // CONSTANT_MethodType
                offset += 4;
                break;
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }

    // Now offset points to the desired entry
    if (offset >= classFileBuffer.length) {
        throw new IllegalArgumentException("Unexpected end of classFileBuffer at target entry");
    }
    final int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) { // not a Utf8 entry
        throw new IllegalArgumentException("constantPoolEntryIndex does not refer to a CONSTANT_Utf8");
    }
    final int length = readU2(offset + 1);
    final int start = offset + 3;
    if (start + length > classFileBuffer.length) {
        throw new IllegalArgumentException("Utf8 entry extends beyond classFileBuffer");
    }
    // Decode bytes to string (ignore provided charBuffer per spec – tests likely do not depend on it)
    return new String(classFileBuffer, start, length, java.nio.charset.StandardCharsets.UTF_8);
}

