private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    // Defensive checks: if predicate or nodes are null, return a circulator at the stop node (if available)
    if (predicate == null) {
        return stop != null ? new OuterFaceCirculator(stop) : null;
    }
    if (start == null) {
        return stop != null ? new OuterFaceCirculator(stop) : null;
    }
    // If stop is null, treat the traversal as unlimited; we simply return the start circulator if predicate matches,
    // otherwise we attempt to continue until we loop back to start.
    OuterFaceCirculator current = new OuterFaceCirculator(start);
    OuterFaceCirculator stopCirculator = stop != null ? new OuterFaceCirculator(stop) : null;
    int direction = dir >= 0 ? 1 : -1; // positive for forward, negative for reverse

    try {
        // Loop until we either find a matching node or reach the stop node (if one is specified)
        while (true) {
            Node currentNode = current.getNode();
            if (predicate.test(currentNode)) {
                return current;
            }
            // If we've reached the stop node (and stopCirculator is defined), stop searching
            if (stopCirculator != null && current.equals(stopCirculator)) {
                break;
            }
            // Move to the next or previous element depending on direction
            if (direction > 0) {
                current = current.next();
            } else {
                current = current.prev();
            }
            // If we loop back to the start without finding a match, break out to avoid infinite loop
            if (current != null && current.equals(new OuterFaceCirculator(start))) {
                // If we returned to the start and no match was found, break
                break;
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return the stop circulator (if available)
        return stopCirculator;
    }

    // Return a circulator pointing at the stop node if it was defined; otherwise return the current circulator.
    return stopCirculator != null ? stopCirculator : current;
}

