public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative: " + byteLength);
    }
    // No bytes to copy, simply return this
    if (byteLength == 0) {
        return this;
    }
    // Validate byteOffset
    if (byteOffset < 0) {
        throw new ArrayIndexOutOfBoundsException("byteOffset must be non‑negative: " + byteOffset);
    }

    // Ensure we have enough space in the internal buffer
    ensureCapacity(length + byteLength);

    if (byteArrayValue == null) {
        // Null source array: put zero bytes
        for (int i = 0; i < byteLength; i++) {
            buffer[length + i] = 0;
        }
    } else {
        // Validate source bounds
        if ((long) byteOffset + byteLength > byteArrayValue.length) {
            throw new ArrayIndexOutOfBoundsException(
                "Requested " + byteLength + " bytes from index " + byteOffset +
                " exceeds source array length " + byteArrayValue.length);
        }
        // Copy bytes from source array
        System.arraycopy(byteArrayValue, byteOffset, buffer, length, byteLength);
    }

    // Update current length
    length += byteLength;
    return this;
}

