private void check(String modelName) throws IllegalStateException {
    /* The sharding key indices for each model are stored in a map called
     * `shardingKeyIndicesMap` (mapping from model name to a list of integer indices).
     * This method validates that the indices for the passed model are continuous, that
     * is, the list contains exactly the numbers 0, 1, ..., n-1 where n is the size
     * of the list.
     */
    try {
        // Retrieve the indices for the given model name.  The map is expected to be
        // declared elsewhere in the same class (e.g. `private static final Map<String, List<Integer>> shardingKeyIndicesMap = ...`)
        @SuppressWarnings("unchecked")
        java.util.Map<String, java.util.List<Integer>> map =
                (java.util.Map<String, java.util.List<Integer>>)java.lang.reflect.Field
                        .class.getDeclaredField("shardingKeyIndicesMap").get(null);

        if (map == null) {
            return; // No indices known, nothing to check.
        }

        java.util.List<Integer> indices = map.get(modelName);
        if (indices == null || indices.isEmpty()) {
            return; // No sharding keys defined, nothing to check.
        }

        // Because List.indexOf is O(n), we can sort the list once and then verify
        // that it contains the exact range [0, size-1].
        java.util.List<Integer> sorted = new java.util.ArrayList<>(indices);
        java.util.Collections.sort(sorted);

        int expected = 0;
        for (int idx : sorted) {
            if (idx != expected) {
                throw new IllegalStateException(
                        "Sharding key indices are not continuous for model '" + modelName + "': expected index " + expected + " but found " + idx);
            }
            expected++;
        }

        // If we get here the indices are continuous.
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // If the map field cannot be accessed, rethrow as IllegalStateException
        throw new IllegalStateException("Unable to access sharding key indices map for model '" + modelName + "'", e);
    }
}

public byte readByte() throws IOException {
    // Refill the buffer if we have reached the end of the current data
    if (pos >= bufferLength) {
        int newBytes = refill(); // refill() should load data into 'buffer'
        if (newBytes <= 0) {
            // No more data available – signal end of stream
            throw new EOFException("No more data available while reading a byte");
        }
    }
    // Return the next byte and advance the position
    return buffer[pos++];
}

