private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel must not be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels must not be null");
    }
    if (bucketsByLabel.isEmpty() || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel is out of bounds: " + minLabel);
    }
    // Handle case when bucket 0 might not exist
    if (bucketsByLabel.get(0) == null) {
        bucketsByLabel.set(0, new HashSet<>());
    }
    Set<Integer> bucketMin = bucketsByLabel.get(minLabel);
    if (bucketMin == null) {
        bucketMin = new HashSet<>();
        bucketsByLabel.set(minLabel, bucketMin);
    }

    if (minLabel == 0) {
        // Moving from bucket 0 to bucket 0: just clear
        bucketMin.clear();
        return;
    }

    Set<Integer> bucketZero = bucketsByLabel.get(0);
    for (Integer v : new HashSet<>(bucketMin)) { // iterate over a copy to avoid concurrent modification
        if (v == null) {
            continue;
        }
        if (v < 0 || v >= labels.size()) {
            throw new IllegalArgumentException("Vertex index out of bounds: " + v);
        }
        labels.set(v, 0);
        bucketZero.add(v);
    }
    bucketMin.clear();
}

