private void pop(final int elements) {
    // Validate the input first
    if (elements < 0) {
        throw new IllegalArgumentException(
                "Cannot pop a negative number of elements: " + elements);
    }

    // Ensure we have enough elements on the stack
    // (Assumes a field named `stack` that holds the frame stack.)
    if (stack == null || elements > stack.size()) {
        throw new IllegalStateException(
                "Attempting to pop " + elements + " elements but only "
                        + (stack == null ? 0 : stack.size()) + " present.");
    }

    // Perform the pop operation
    for (int i = 0; i < elements; i++) {
        stack.pop();
    }
}

public boolean isCompatible(DataTable dataset){
    if (dataset == null) {
        return false;
    }
    try {
        // Retrieve the bucket from the dataset via a method called getBucket()
        java.lang.reflect.Method getBucketMethod = dataset.getClass().getMethod("getBucket");
        Object datasetBucket = getBucketMethod.invoke(dataset);

        // Attempt to retrieve the bucket of this instance (assuming a field named 'bucket')
        java.lang.reflect.Field bucketField;
        try {
            bucketField = this.getClass().getDeclaredField("bucket");
        } catch (NoSuchFieldException e) {
            // No bucket field in this class – cannot compare
            return false;
        }
        bucketField.setAccessible(true);
        Object ownBucket = bucketField.get(this);

        // Compare the two buckets safely
        return java.util.Objects.equals(datasetBucket, ownBucket);
    } catch (Exception e) {
        // Any reflection or invocation error means we cannot guarantee compatibility
        return false;
    }
}

