        throw new IllegalArgumentException(
            "Invalid range: from=" + from + ", to=" + to + ", array length=" + len
        );
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Defensive check: if the source is null, identical to destination, or empty, do nothing.
    if (list == null || list == this || list.size == 0) {
        return;
    }

    // Grab first and last real nodes of the source list.
    // It is assumed that each list contains two sentinel nodes: head and tail.
    // The first real node is head.next; the last real node is tail.prev.
    final ListNodeImpl<E> srcFirst  = list.head.next;
    final ListNodeImpl<E> srcLast   = list.tail.prev;

    // Sanity check for an empty source list (should have been caught earlier).
    if (srcFirst == list.tail) {
        return;
    }

    // Preserve the number of nodes that will be moved.
    final int movedSize = list.size;

    // If this list is empty, simply point its sentinels to the source nodes.
    if (this.head.next == this.tail) {
        this.head.next = srcFirst;
        srcFirst.prev = this.head;
        this.tail.prev = srcLast;
        srcLast.next = this.tail;
    } else {
        // Connect the tail of this list to the first node of the source.
        final ListNodeImpl<E> thisLast = this.tail.prev;
        thisLast.next = srcFirst;
        srcFirst.prev = thisLast;

        // Connect the last node of the source to the tail sentinel of this list.
        this.tail.prev = srcLast;
        srcLast.next = this.tail;
    }

    // Clear the source list: reset its sentinels and size.
    list.head.next = list.tail;
    list.tail.prev = list.head;
    list.size = 0;

    // Update the destination list's size.
    this.size += movedSize;
}

