public int decide(LoggingEvent event){
    try {
        // If the event itself is null, we cannot evaluate the message, so stay neutral.
        if (event == null) {
            return Filter.NEUTRAL;
        }

        // Safely obtain the formatted message; a null message still results in neutrality.
        String message = event.getFormattedMessage();
        if (message == null) {
            return Filter.NEUTRAL;
        }

        // Assume there is a field named `pattern` that holds the string pattern we are looking for.
        // If the pattern is null, nothing matches, so we stay neutral.
        if (pattern == null) {
            return Filter.NEUTRAL;
        }

        // If the message contains the required pattern, accept the event; otherwise stay neutral.
        return message.contains(pattern) ? Filter.ACCEPT : Filter.NEUTRAL;
