    // and writable in the target. Any failure while accessing a property
    // is caught and ignored so that the copy proceeds for the remaining
    // properties.
    try {
        java.util.Set<?> sourceKeys = map.keySet();
        for (Object key : sourceKeys) {
            try {
                Object value = map.get(key);
                this.put(key, value);
            } catch (Exception e) {
                // Ignore properties that cannot be read from the source
                // (e.g., write‑only) or written into the target (e.g., read‑only).
                // e may also be BeanMapPropertyNotFoundException or similar.
            }
        }
    } catch (Exception e) {
        // Ignore errors while iterating over the source keys.
    }
}

