    // Return immediately if request is null
    if (r == null) {
        return null;
    }

    // 1. Attempt to retrieve a pre‑stored Meteor instance from a request attribute
    try {
        Object attr = r.getAttribute("meteor");
        if (attr instanceof Meteor) {
            return (Meteor) attr;
        }
    } catch (Exception ignore) {
        // In case the servlet container throws an unexpected exception,
        // just ignore and continue to next lookup strategy.
    }

    // 2. Attempt to retrieve a Meteor instance from the HTTP session,
    // if a session exists and contains the attribute.
    try {
        javax.servlet.http.HttpSession session = r.getSession(false);
        if (session != null) {
            Object sessAttr = session.getAttribute("meteor");
            if (sessAttr instanceof Meteor) {
                return (Meteor) sessAttr;
            }
        }
    } catch (Exception ignore) {
        // Ignore any exception that may arise from accessing the session.
    }

    // 3. Attempt to resolve a Meteor by an identifier supplied as a request
    // parameter (e.g., "meteorId").  We conservatively try to call a
    // public static method named "forId" on the Meteor class which takes a
    // String argument and returns a Meteor instance.  This logic uses
    // reflection, so it will silently fail if the method does not exist.
    try {
        String meteorId = r.getParameter("meteorId");
        if (meteorId != null && !meteorId.isEmpty()) {
            java.lang.reflect.Method forIdMethod = Meteor.class.getMethod("forId", String.class);
            Object result = forIdMethod.invoke(null, meteorId);
            if (result instanceof Meteor) {
                return (Meteor) result;
            }
        }
    } catch (NoSuchMethodException e) {
        // The Meteor class does not expose a method forId(String).  Ignore.
    } catch (Exception ignore) {
        // Any other reflection‑related or runtime exception is ignored.
    }

    // 4. If all strategies fail, return null indicating that no Meteor
    // instance could be found for the provided request.
    return null;
}

