private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertex set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // empty or single-element set is trivially a clique
    }
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < list.size(); i++) {
        V u = list.get(i);
        for (int j = i + 1; j < list.size(); j++) {
            V v = list.get(j);
            // Check for an edge in either direction (handles undirected graphs where getEdge may be order-sensitive)
            if (graph.getEdge(u, v) == null && graph.getEdge(v, u) == null) {
                return false; // missing edge => not a clique
            }
        }
    }
    return true; // all pairs are connected
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    List<K> sorted = new ArrayList<>(keys);
    try{
        sorted.sort(null);
    } catch (ClassCastException e){
        throw new IllegalArgumentException("Keys must be comparable", e);
    }
    for (K key : keys){
        if (key == null){
            result.add(-1);
            continue;
        }
        int insertionIndex = lowerBoundIndex(key, sorted);
        int lowerIdx = insertionIndex - 1;
        if (lowerIdx < 0){
            result.add(-1);
        } else {
            K lowerKey = sorted.get(lowerIdx);
            if (lowerKey instanceof Integer){
                result.add((Integer) lowerKey);
            } else {
                result.add(-1);
            }
        }
    }
    return result;
}

private int lowerBoundIndex(K target, List<K> sorted){
    int low = 0;
    int high = sorted.size();
    while (low < high){
        int mid = (low + high) >>> 1;
        @SuppressWarnings("unchecked")
        Comparable<K> cmp = (Comparable<K>) sorted.get(mid);
        if (cmp.compareTo(target) < 0){
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    int idx = 0;
    // Detect whether descriptor is a method descriptor
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        // Skip '('
        idx++;
        // Pop argument types
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            idx = consumeTypeAndPop(descriptor, idx);
        }
        if (idx >= descriptor.length() || descriptor.charAt(idx) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        // Skip ')', return type is ignored
        idx++;
    }
    // If not a method descriptor, or after method arguments, process remaining type descriptor
    while (idx < descriptor.length()) {
        idx = consumeTypeAndPop(descriptor, idx);
    }
}

private int consumeTypeAndPop(final String descriptor, int idx) {
    if (idx >= descriptor.length()) {
        throw new IllegalArgumentException("Unexpected end of descriptor");
    }
    char c = descriptor.charAt(idx);
    switch (c) {
        case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
            popSlot();
            return idx + 1;
        case 'J': case 'D':
            // Long and double take two slots
            popSlot();
            popSlot();
            return idx + 1;
        case '[':
            idx++; // consume '['
            // Consume element type of the array
            while (idx < descriptor.length() && descriptor.charAt(idx) == '[') {
                idx++; // consume additional '[' for multi-dimensional arrays
            }
            if (idx >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
            }
            if (descriptor.charAt(idx) == 'L') {
                int semicolon = descriptor.indexOf(';', idx);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                idx = semicolon + 1; // consume until ';'
            } else {
                idx++; // primitive component
            }
            // The array itself occupies one slot on the stack
            popSlot();
            return idx;
        case 'L':
            int semicolon = descriptor.indexOf(';', idx);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            popSlot();
            return semicolon + 1;
        default:
            throw new IllegalArgumentException("Unknown descriptor character: " + c);
    }
}

