public static String applyRelativePath(String path, String relativePath){
    // Validate input
    if (path == null || relativePath == null) {
        return null;
    }

    // Trim inputs to avoid accidental spaces affecting logic
    path = path.trim();
    relativePath = relativePath.trim();

    // If relativePath is empty just return the original path
    if (relativePath.isEmpty()) {
        return path.isEmpty() ? "" : path;
    }

    try {
        Deque<String> stack = new ArrayDeque<>();

        // Determine if relativePath is root-relative (starts with '/')
        boolean rootRelative = relativePath.startsWith("/");

        // If not root-relative, initialize stack with base path components
        if (!rootRelative) {
            if (!path.isEmpty()) {
                String[] baseParts = path.split("/");
                for (String part : baseParts) {
                    if (part.isEmpty() || part.equals(".")) {
                        continue; // skip empty or current directory markers
                    }
                    stack.addLast(part);
                }
            }
        }

        // Process relative path components
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue; // ignore empty or current directory entries
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast(); // move up one directory
                }
                // If stack was empty, just stay at root (ignore extra '..')
            } else {
                stack.addLast(part); // go into the subdirectory/file
            }
        }

        // Build the resulting path
        StringBuilder result = new StringBuilder();

        // Preserve leading slash if either the original path started with it or the relative path was root-relative
        boolean leadingSlash = (!path.isEmpty() && path.startsWith("/")) || rootRelative;
        if (leadingSlash) {
            result.append("/");
        }

        // Join the stack components with '/'
        boolean first = !result.toString().isEmpty(); // whether we already have a slash
        for (String comp : stack) {
            if (first) {
                result.append(comp);
                first = false;
            } else {
                result.append("/").append(comp);
            }
        }

        // Special case: if result is empty and we had a leading slash, return "/"
        if (result.length() == 0 && leadingSlash) {
            return "/";
        }

        // If result is still empty (no components), return empty string
        return result.toString();
    } catch (Exception e) {
        // In case of any unforeseen runtime issues return null
        return null;
    }
}

