static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return null;
    }

    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }

    if (nullCount == 0) {
        // array has no nulls – we can safely treat it as a String array
        @SuppressWarnings("unchecked")
        String[] stringArray = (String[]) array;
        return stringArray;
    }

    // Build a new array that excludes null entries
    int nonNullSize = array.length - nullCount;
    String[] result = new String[nonNullSize];
    int pos = 0;
    for (Object o : array) {
        if (o != null) {
            result[pos++] = String.valueOf(o);
        }
    }
    return result;
}

