public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    // Handle null inputs
    if (str == null || substring == null) {
        return false;
    }
    // Empty substring always matches at any valid index (including end position)
    int substrLen = substring.length();
    if (substrLen == 0) {
        return index >= 0 && index <= str.length();
    }
    // Negative index or index beyond string length is invalid
    if (index < 0 || index > str.length() - substrLen) {
        return false;
    }
    // Compare character by character
    for (int i = 0; i < substrLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    // Guard against null event or client list
    if (event == null || clientStreams == null) {
        return;
    }

    String message = event.getRenderedMessage();
    // Append a line separator so each message is on its own line
    String line = message + System.lineSeparator();
    byte[] data;
    try {
        data = line.getBytes("UTF-8");
    } catch (java.io.UnsupportedEncodingException e) {
        // Fallback to platform default if UTF-8 is somehow unsupported
        data = line.getBytes();
    }

    // Synchronize on the collection of client streams to avoid concurrent modification
    Object sync = clientStreams;
    synchronized (sync) {
        java.util.Iterator<java.io.OutputStream> it = clientStreams.iterator();
        while (it.hasNext()) {
            java.io.OutputStream out = it.next();
            try {
                out.write(data);
                out.flush();
            } catch (java.io.IOException e) {
                // If writing to a client fails, close the stream and remove it
                try {
                    out.close();
                } catch (java.io.IOException ignored) {
                }
                it.remove();
                // Optionally, log the exception so the failure is visible
                // (Assuming a logger named 'log' is available)
                if (log != null) {
                    log.warn("Failed to send log message to a client; stream removed.", e);
                }
            }
        }
    }
}

