private void checkIfPackedField() throws IOException {
    // The wire type is stored in the lower three bits of the last read tag.
    int wireType = currentTag & 0x07;
    // In the protobuf encoding, a repeated primitive field can be packed
    // by using a length-delimited field (wire type == 2).  If the field
    // descriptor indicates that this field is repeated and the wire type
    // matches, we treat the following length-delimited block as packed
    // data and update the internal parser state accordingly.
    if (isRepeated && wireType == 2) { // 2 == LENGTH_DELIMITED
        // Mark that we are now reading a packed field.
        isPacked = true;
        // Read the length of the packed region and store the end position.
        int packedLen = readRawVarint32();
        packedEnd = currentPos + packedLen;
    } else {
        // Not a packed field; ensure packed state is cleared.
        isPacked = false;
    }
}

public int readTag() throws IOException {
    try {
        int tag = readRawVarint32();
        // In protocol buffers a tag of 0 is reserved for end-of-message
        // and should be treated as the end of the input.
        return (tag != 0) ? tag : 0;
    } catch (EOFException e) {
        // Reached end of the stream; no more tags
        return 0;
    }
}

