                endField.setAccessible(true);
                break;
            }catch(NoSuchFieldException ignored){}
        }
        // Attempt to find total length field
        for(String name: new String[]{"total","contentLength","length","fileLength","totalLength"}){
            try{
                totalField=this.getClass().getDeclaredField(name);
                totalField.setAccessible(true);
                break;
            }catch(NoSuchFieldException ignored){}
        }
        if(startField==null || endField==null || totalField==null) return null;
        Object sObj=startField.get(this);
        Object eObj=endField.get(this);
        Object tObj=totalField.get(this);
        long start = sObj instanceof Number ? ((Number)sObj).longValue() : Long.parseLong(sObj.toString());
        long end   = eObj instanceof Number ? ((Number)eObj).longValue() : Long.parseLong(eObj.toString());
        long total = tObj instanceof Number ? ((Number)tObj).longValue() : Long.parseLong(tObj.toString());
        return "bytes "+start+"-"+end+"/"+total;
    }catch(Exception e){
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File does not exist: " + file);
    }
    // Assume there is a helper that parses all snapshots from the file.
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);
    List<ThreadSnapshot> result = new ArrayList<>();

    if (timeRanges == null || timeRanges.isEmpty() || allSnapshots == null || allSnapshots.isEmpty()) {
        return result; // No data or no ranges, return empty list
    }

    for (ThreadSnapshot ts : allSnapshots) {
        long timestamp;
        try {
            timestamp = ts.getTimestamp();
        } catch (Exception e) {
            // If the snapshot doesn't expose its timestamp, skip it
            continue;
        }
        for (ProfileAnalyzeTimeRange tr : timeRanges) {
            if (tr == null) continue;
            long start = tr.getStartTime();
            long end = tr.getEndTime();
            if (start <= timestamp && timestamp <= end) {
                result.add(ts);
                break;
            }
        }
    }
    return result;
}
